def main() -> None:
    for book_id, chapters in BOOKS.items():
        payload = {
            "book_id": book_id,
            "chapters": [
                {
                    "number": number,
                    "test": [choice(*question) for question in questions],
                }
                for number, questions in enumerate(chapters, start=1)
            ],
        }
        path = ROOT / "content_tests" / f"{book_id}.json"
        raw = json.dumps(payload, ensure_ascii=False, indent=2) + "\n"
        for source, replacement in REPLACEMENTS.items():
            raw = raw.replace(source, replacement)
        path.write_text(
            raw,
            encoding="utf-8",
        )
        print(path.relative_to(ROOT))


if __name__ == "__main__":
    main()
